-- MLOS V3 Onion + MCQ-first evaluation upgrade
-- Run after deploying the V3 changed files.
BEGIN;

-- Make onion topics appear before the old bottom-up path. Idempotent: only shifts once.
UPDATE mlos_topic_catalog SET sequence_no = sequence_no + 100, updated_at = now() WHERE sequence_no BETWEEN 1 AND 99 AND topic_id NOT LIKE 'aia_%' AND topic_id NOT LIKE 'genai_%' AND topic_id NOT LIKE 'rag_%' AND topic_id NOT LIKE 'llm_%' AND topic_id NOT LIKE 'trf_%';

