INSERT INTO mlos_topic_learning_designs(topic_id,design_version,learning_design,is_active,created_at,updated_at)
VALUES ('aia_001', 'mlos_v3_onion_mcq_tutor_2026_06_28', $mlos_json${"topic_id": "aia_001", "title": "Agentic AI outer layer: what agents actually do", "design_version": "mlos_v3_onion_mcq_tutor_2026_06_28", "assessment_mode": "v3_mcq_first_plus_short_response", "learning_objective": "Explain Agentic AI as a system that uses an LLM inside a controlled loop of goal, planning, tool use, observation and stopping criteria.", "prerequisite_bridge": "This is part of the onion path: start from the AI system you need to architect, then peel down only when the next layer explains a design choice or failure.", "concept_steps": [{"heading": "Start from the outside", "body": "An agent is not magic autonomy. It is a workflow where an LLM helps decide the next step, calls tools, reads results, and continues until a goal or stop rule is met."}, {"heading": "What changes from a chatbot", "body": "A chatbot mainly responds. An agent can act through tools: search, query a database, update a ticket, write code, call an API, or ask a human for approval."}, {"heading": "Why this matters architecturally", "body": "The hard part is not the prompt. The hard part is controlling actions, permissions, memory, tool errors, cost, evaluation, audit trail and human intervention."}, {"heading": "Failure mode", "body": "If the system has vague goals, unsafe tools or no stop condition, the agent can loop, act on bad evidence, or create unreviewed operational changes."}], "worked_example": {"scenario": "A service agent checks a warranty claim, retrieves vehicle history, calls a policy tool, drafts a response and routes uncertain cases to a human.", "takeaway": "The architecture is the loop and controls around the model, not only the model."}, "worked_examples": [{"title": "Architect readout", "body": "A service agent checks a warranty claim, retrieves vehicle history, calls a policy tool, drafts a response and routes uncertain cases to a human. The architecture is the loop and controls around the model, not only the model. The design decision is to make the capability useful only inside explicit evidence, permission and monitoring boundaries."}], "misconception": "Calling any chatbot an agent because it sounds proactive.", "architect_extension": "Define allowed tools, action boundaries, memory scope, human approval points, evaluation traces and rollback path.", "knowledge_checks": [{"id": "mcq_01", "kind": "Critical", "is_critical": true, "question": "What is the central idea of Agentic AI outer layer: what agents actually do?", "options": ["Explain Agentic AI as a system that uses an LLM inside a controlled loop of goal, planning, tool use, observation and stopping criteria.", "A guarantee that AI output is correct", "A UI style choice", "A reason to skip evaluation"], "answer_index": 0, "explanation": "The correct option states the mechanism and its boundary.", "option_explanations": ["The correct option states the mechanism and its boundary.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism."]}, {"id": "mcq_02", "kind": "Critical", "is_critical": true, "question": "Which statement is unsafe?", "options": ["Calling any chatbot an agent because it sounds proactive.", "Define evidence before action", "Track failures and cost", "Use human approval where impact is high"], "answer_index": 0, "explanation": "The unsafe option is the common wrong mental model.", "option_explanations": ["The unsafe option is the common wrong mental model.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism."]}, {"id": "mcq_03", "kind": "Critical", "is_critical": true, "question": "What makes this architect-level?", "options": ["Define allowed tools, action boundaries, memory scope, human approval points, evaluation traces and rollback path.", "More buzzwords", "Longer explanations", "Only model selection"], "answer_index": 0, "explanation": "Architecture connects capability to controls and operating decisions.", "option_explanations": ["Architecture connects capability to controls and operating decisions.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism."]}, {"id": "mcq_04", "kind": "Scenario", "is_critical": false, "question": "What should you check before production use?", "options": ["Evidence quality, permissions, monitoring and failure response", "Only demo output", "Only prompt length", "Only model popularity"], "answer_index": 0, "explanation": "Production use needs evidence and controls.", "option_explanations": ["Production use needs evidence and controls.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism."]}, {"id": "mcq_05", "kind": "Scenario", "is_critical": false, "question": "What is a strong answer pattern?", "options": ["Mechanism, example, risk, control", "Definition only", "Vendor names only", "Confidence only"], "answer_index": 0, "explanation": "The answer should move from concept to operating consequence.", "option_explanations": ["The answer should move from concept to operating consequence.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism."]}, {"id": "mcq_06", "kind": "Scenario", "is_critical": false, "question": "What should not be hidden?", "options": ["Owner, trigger, action and evaluation criterion", "Color theme", "Model nickname", "Personal preference"], "answer_index": 0, "explanation": "Governance needs explicit accountability.", "option_explanations": ["Governance needs explicit accountability.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism."]}, {"id": "mcq_07", "kind": "Scenario", "is_critical": false, "question": "What is the best learning approach here?", "options": ["Use the AI system first, then peel down to the layer that explains the failure or design choice", "Memorize every formula first", "Skip fundamentals forever", "Only read papers"], "answer_index": 0, "explanation": "This is the onion approach.", "option_explanations": ["This is the onion approach.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism."]}, {"id": "mcq_08", "kind": "Scenario", "is_critical": false, "question": "What is a common production failure?", "options": ["The system acts on weak context or unverified output", "Too many examples in the lesson", "All users become experts", "No need for logs"], "answer_index": 0, "explanation": "Evidence/action mismatch is a real failure.", "option_explanations": ["Evidence/action mismatch is a real failure.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism."]}, {"id": "mcq_09", "kind": "Scenario", "is_critical": false, "question": "What should an architect ask?", "options": ["What can the system do, what evidence supports it, who approves it, and what happens when it fails?", "Can we call it AI?", "Can we avoid metrics?", "Can we ignore users?"], "answer_index": 0, "explanation": "Good architecture asks capability, evidence, approval and failure questions.", "option_explanations": ["Good architecture asks capability, evidence, approval and failure questions.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism."]}, {"id": "mcq_10", "kind": "Scenario", "is_critical": false, "question": "What should evaluation measure?", "options": ["Task success, groundedness, safety, cost, latency and operating fit", "Only whether the answer sounds fluent", "Only token count", "Only one happy-path demo"], "answer_index": 0, "explanation": "AI system evaluation must match the production decision.", "option_explanations": ["AI system evaluation must match the production decision.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism."]}], "evidence_tasks": [{"question_id": "q1", "type": "architect_decision", "label": "Short architect response", "purpose": "Use one concrete scenario to prove you understand the layer and its operating control.", "question": "In 80-140 words, explain Agentic AI outer layer: what agents actually do using one business or engineering example. Include the mechanism, one risk, and one control.", "expected_focus": ["mechanism", "example", "risk", "control"], "response_shape": "Mechanism, example, risk, control.", "target_min_words": 80, "target_max_words": 140}], "assessment_principle": "V3 normal lesson: MCQs test breadth; one short response tests architect reasoning. Do not require five essay answers.", "answer_quality_bar": {"three_star": "Mechanism + example + risk + one control.", "four_star": "Adds trade-off and evidence criterion.", "five_star": "Adds owner, trigger, monitoring and fallback."}}$mlos_json$::jsonb, true, now(), now())
ON CONFLICT (topic_id) DO UPDATE SET
