VALUES ('aia_002', 'mlos_v3_onion_mcq_tutor_2026_06_28', $mlos_json${"topic_id": "aia_002", "title": "Agent loop: goal, plan, tool, observe", "design_version": "mlos_v3_onion_mcq_tutor_2026_06_28", "assessment_mode": "v3_mcq_first_plus_short_response", "learning_objective": "Break an agent into the loop: goal, plan, tool call, observation, state update, decision and stop condition.", "prerequisite_bridge": "This is part of the onion path: start from the AI system you need to architect, then peel down only when the next layer explains a design choice or failure.", "concept_steps": [{"heading": "Goal", "body": "The goal must be explicit enough to decide success. 'Help user' is weak. 'Find open warranty cases missing evidence and draft a review note' is usable."}, {"heading": "Plan and tool call", "body": "The LLM proposes a step, but the runtime controls whether that tool is allowed, with what parameters, and under what permission."}, {"heading": "Observe and update state", "body": "Tool results are evidence. The agent must update its state from actual tool output, not assume the call worked."}, {"heading": "Stop rule", "body": "A production agent needs stopping criteria: success, uncertainty, max steps, cost limit, timeout, or human escalation."}], "worked_example": {"scenario": "An engineering assistant plans to fetch requirements, compare them to test cases, flag missing traceability and stop after the report is created.", "takeaway": "The loop must be observable and bounded."}, "worked_examples": [{"title": "Architect readout", "body": "An engineering assistant plans to fetch requirements, compare them to test cases, flag missing traceability and stop after the report is created. The loop must be observable and bounded. The design decision is to make the capability useful only inside explicit evidence, permission and monitoring boundaries."}], "misconception": "Letting the model freely decide tools, steps and completion with no runtime control.", "architect_extens