INSERT INTO mlos_topic_learning_designs(topic_id,design_version,learning_design,is_active,created_at,updated_at)
VALUES ('aia_003', 'mlos_v3_onion_mcq_tutor_2026_06_28', $mlos_json${"topic_id": "aia_003", "title": "Tools, memory, guardrails and human checkpoints", "design_version": "mlos_v3_onion_mcq_tutor_2026_06_28", "assessment_mode": "v3_mcq_first_plus_short_response", "learning_objective": "Design practical controls for agent tools, memory, guardrails and human checkpoints.", "prerequisite_bridge": "This is part of the onion path: start from the AI system you need to architect, then peel down only when the next layer explains a design choice or failure.", "concept_steps": [{"heading": "Tools are permissions", "body": "Every tool gives the agent a capability. Read-only search is lower risk than write access to CRM, email, code, or production systems."}, {"heading": "Memory is scoped state", "body": "Memory should be task-relevant and governed. Unlimited memory can leak stale facts, private data, or irrelevant context into decisions."}, {"heading": "Guardrails are not one filter", "body": "Use input constraints, tool permissioning, output checks, policy checks, cost/time limits and human approval for high-impact actions."}, {"heading": "Human checkpoint", "body": "The human checkpoint should sit before irreversible or high-cost action, not after damage is done."}], "worked_example": {"scenario": "A procurement agent can read supplier documents and draft recommendations, but cannot send purchase orders without approval.", "takeaway": "Autonomy is a graduated permission model."}, "worked_examples": [{"title": "Architect readout", "body": "A procurement agent can read supplier documents and draft recommendations, but cannot send purchase orders without approval. Autonomy is a graduated permission model. The design decision is to make the capability useful only inside explicit evidence, permission and monitoring boundaries."}], "misconception": "Adding a generic safety prompt and assuming the agent is governed.", "architect_extension": "Define tool risk tiers, memory retention, approval gates, audit logs, and exception handling.", "knowledge_checks": [{"id": "mcq_01", "kind": "Critical", "is_critical": true, "question": "What is the central idea of Tools, memory, guardrails and human checkpoints?", "options": ["Design practical controls for agent tools, memory, guardrails and human checkpoints.", "A guarantee that AI output is correct", "A UI style choice", "A reason to skip evaluation"], "answer_index": 0, "explanation": "The correct option states the mechanism and its boundary.", "option_explanations": ["The correct option states the mechanism and its boundary.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism."]}, {"id": "mcq_02", "kind": "Critical", "is_critical": true, "question": "Which statement is unsafe?", "options": ["Adding a generic safety prompt and assuming the agent is governed.", "Define evidence before action", "Track failures and cost", "Use human approval where impact is high"], "answer_index": 0, "explanation": "The unsafe option is the common wrong mental model.", "option_explanations": ["The unsafe option is the common wrong mental model.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism."]}, {"id": "mcq_03", "kind": "Critical", "is_critical": true, "question": "What makes this architect-level?", "options": ["Define tool risk tiers, memory retention, approval gates, audit logs, and exception handling.", "More buzzwords", "Longer explanations", "Only model selection"], "answer_index": 0, "explanation": "Architecture connects capability to controls and operating decisions.", "option_explanations": ["Architecture connects capability to controls and operating decisions.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism."]}, {"id": "mcq_04", "kind": "Scenario", "is_critical": false, "question": "What should you check before production use?", "options": ["Evidence quality, permissions, monitoring and failure response", "Only demo output", "Only prompt length", "Only model popularity"], "answer_index": 0, "explanation": "Production use needs evidence and controls.", "option_explanations": ["Production use needs evidence and controls.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism."]}, {"id": "mcq_05", "kind": "Scenario", "is_critical": false, "question": "What is a strong answer pattern?", "options": ["Mechanism, example, risk, control", "Definition only", "Vendor names only", "Confidence only"], "answer_index": 0, "explanation": "The answer should move from concept to operating consequence.", "option_explanations": ["The answer should move from concept to operating consequence.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism."]}, {"id": "mcq_06", "kind": "Scenario", "is_critical": false, "question": "What should not be hidden?", "options": ["Owner, trigger, action and evaluation criterion", "Color theme", "Model nickname", "Personal preference"], "answer_index": 0, "explanation": "Governance needs explicit accountability.", "option_explanations": ["Governance needs explicit accountability.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism."]}, {"id": "mcq_07", "kind": "Scenario", "is_critical": false, "question": "What is the best learning approach here?", "options": ["Use the AI system first, then peel down to the layer that explains the failure or design choice", "Memorize every formula first", "Skip fundamentals forever", "Only read papers"], "answer_index": 0, "explanation": "This is the onion approach.", "option_explanations": ["This is the onion approach.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism."]}, {"id": "mcq_08", "kind": "Scenario", "is_critical": false, "question": "What is a common production failure?", "options": ["The system acts on weak context or unverified output", "Too many examples in the lesson", "All users become experts", "No need for logs"], "answer_index": 0, "explanation": "Evidence/action mismatch is a real failure.", "option_explanations": ["Evidence/action mismatch is a real failure.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism."]}, {"id": "mcq_09", "kind": "Scenario", "is_critical": false, "question": "What should an architect ask?", "options": ["What can the system do, what evidence supports it, who approves it, and what happens when it fails?", "Can we call it AI?", "Can we avoid metrics?", "Can we ignore users?"], "answer_index": 0, "explanation": "Good architecture asks capability, evidence, approval and failure questions.", "option_explanations": ["Good architecture asks capability, evidence, approval and failure questions.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism."]}, {"id": "mcq_10", "kind": "Scenario", "is_critical": false, "question": "What should evaluation measure?", "options": ["Task success, groundedness, safety, cost, latency and operating fit", "Only whether the answer sounds fluent", "Only token count", "Only one happy-path demo"], "answer_index": 0, "explanation": "AI system evaluation must match the production decision.", "option_explanations": ["AI system evaluation must match the production decision.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism.", "This option is either overclaiming, too vague, or misses the operating mechanism."]}], "evidence_tasks": [{"question_id": "q1", "type": "architect_decision", "label": "Short architect response", "purpose": "Use one concrete scenario to prove you understand the layer and its operating control.", "question": "In 80-140 words, explain Tools, memory, guardrails and human checkpoints using one business or engineering example. Include the mechanism, one risk, and one control.", "expected_focus": ["mechanism", "example", "risk", "control"], "response_shape": "Mechanism, example, risk, control.", "target_min_words": 80, "target_max_words": 140}], "assessment_principle": "V3 normal lesson: MCQs test breadth; one short response tests architect reasoning. Do not require five essay answers.", "answer_quality_bar": {"three_star": "Mechanism + example + risk + one control.", "four_star": "Adds trade-off and evidence criterion.", "five_star": "Adds owner, trigger, monitoring and fallback."}}$mlos_json$::jsonb, true, now(), now())
