VALUES ('rag_001', 'mlos_v3_onion_mcq_tutor_2026_06_28', $mlos_json${"topic_id": "rag_001", "title": "RAG: retrieval before generation", "design_version": "mlos_v3_onion_mcq_tutor_2026_06_28", "assessment_mode": "v3_mcq_first_plus_short_response", "learning_objective": "Explain RAG as retrieving trusted context before generation so the model answers from supplied evidence instead of memory alone.", "prerequisite_bridge": "This is part of the onion path: start from the AI system you need to architect, then peel down only when the next layer explains a design choice or failure.", "concept_steps": [{"heading": "Why RAG exists", "body": "LLMs may not know your private or latest documents. RAG fetches relevant chunks and puts them into the prompt as evidence."}, {"heading": "Retrieval quality", "body": "Bad retrieval means the model receives weak or wrong evidence. Good generation cannot recover from missing source context."}, {"heading": "Grounded answer", "body": "The response should use retrieved evidence, cite or point to it where needed, and avoid unsupported claims."}, {"heading": "Production controls", "body": "Track retrieval hit rate, source quality, chunking, access permissions, hallucination rate and user feedback."}], "worked_example": {"scenario": "A support bot retrieves the latest service bulletin before answering a technician question.", "takeaway": "RAG is an evidence pipeline plus a generation step."}, "worked_examples": [{"title": "Architect readout", "body": "A support bot retrieves the latest service bulletin before answering a technician question. RAG is an evidence pipeline plus a generation step. The design decision is to make the capability useful only inside explicit evidence, permission and monitoring boundaries."}], "misconception": "Believing RAG automatically prevents hallucination.", "architect_extension": "Govern document ingestion, chunking, embeddings, retrieval ranking, access control, citations and answer evaluation.", "knowledge_check